\documentclass[border=10pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    xlabel={$x$},
    ylabel={$y$},
    title={Cross-section in $xy$-plane (Ellipse)},
    width=10cm,
    height=8cm,
    xmin=-1.5, xmax=1.5,
    ymin=-2.5, ymax=2.5,
    axis equal image,
    grid=major,
    ticks=normal
]
% Parametric ellipse: x = cos(t), y = 2*sin(t)
\addplot[
    domain=0:6.28,
    samples=100,
    blue,
    thick,
    fill=blue!20
] (
    {cos(x)},
    {2*sin(x)}
);

% Mark vertices
\addplot[only marks, mark=*, red] coordinates {(1,0) (-1,0) (0,2) (0,-2)};

% Labels for vertices
\node[right] at (axis cs:1,0) {$(1,0)$};
\node[left] at (axis cs:-1,0) {$(-1,0)$};
\node[above] at (axis cs:0,2) {$(0,2)$};
\node[below] at (axis cs:0,-2) {$(0,-2)$};
\end{axis}
\end{tikzpicture}
\end{document}

